import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {sum} from './sum.mjs';

assert.equal(sum(7,3),10);
assert.equal(sum(-2,3),1);

function checkCli(args, expected) {
  const result = spawnSync(process.execPath, ['./cli.mjs', ...args], {encoding: 'utf8'});
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stdout.trim(), String(expected));
}

checkCli(['7', '3'], 10);
checkCli(['-2', '3'], 1);
checkCli(['--multiply', '7', '3'], 21);
checkCli(['--multiply', '-2', '3'], -6);
console.log('2 sum assertions and 4 CLI checks pass');

import {sum} from './sum.mjs';

const multiply = process.argv[2] === '--multiply';
const offset = multiply ? 3 : 2;
const a = Number(process.argv[offset]);
const b = Number(process.argv[offset + 1]);
console.log(multiply ? a * b : sum(a, b));
